changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.taxonomy_unassigned_chashes_384( p_collection text, p_limit int, p_after text ) RETURNS TABLE(has_taxonomy boolean, chashes text[], next_after text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ WITH has_tax AS ( SELECT EXISTS ( SELECT 1 FROM nexus.taxonomy_centroids ct WHERE ct.collection = p_collection AND ct.embedding_384 IS NOT NULL ) AS v ), unassigned AS ( SELECT c.chash FROM nexus.chunks c WHERE c.collection = p_collection AND c.embedding_384 IS NOT NULL AND (SELECT v FROM has_tax) AND (p_after IS NULL OR c.chash > decode(p_after, 'hex')) AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks mc WHERE mc.collection = c.collection AND mc.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.topic_assignments ta JOIN nexus.topics t ON t.id = ta.topic_id WHERE ta.doc_id = c.chash AND t.collection = p_collection ) ORDER BY c.chash LIMIT p_limit ), agg AS ( SELECT array_agg(encode(u.chash, 'hex') ORDER BY u.chash) AS hexes, count(*) AS n FROM unassigned u ) SELECT (SELECT v FROM has_tax) AS has_taxonomy, COALESCE((SELECT hexes FROM agg), ARRAY[]::text[]) AS chashes, CASE WHEN (SELECT n FROM agg) >= p_limit THEN (SELECT hexes[array_length(hexes, 1)] FROM agg) ELSE NULL END AS next_after $$;
