rollback.sql:
DROP FUNCTION IF EXISTS nexus.taxonomy_unassigned_chashes_384(text, int, text);
DROP FUNCTION IF EXISTS nexus.taxonomy_unassigned_chashes_768(text, int, text);
DROP FUNCTION IF EXISTS nexus.taxonomy_unassigned_chashes_1024(text, int, text);
